B.atT=new A.Z("DsBreakpoints.expanded","double","840","Lower bound of the expanded window class.")
B.avU=new A.Z("DsBreakpoints.contentMaxWidth","double","960","The cap on main content width on wide screens. DsPageScaffold applies it by default and centres the surplus.")
B.a_j=s([B.avl,B.atT,B.avU],t.g)
B.awL=new A.e9(null,B.a_j)
